std::vector<int> counting_sort(const std::vector<int>& input)
{
    // Handle empty input
    if (input.empty()) {
        std::cerr << "Input list is empty" << std::endl;
        return {};
    }

    // Find the range of values in the input
    int min_val = *std::min_element(input.begin(), input.end());
    int max_val = *std::max_element(input.begin(), input.end());

    // Handle non-integer input
    if (min_val < std::numeric_limits<int>::min() || 
        max_val > std::numeric_limits<int>::max()) {
        std::cerr << "Input list contains non-integer values" << std::endl;
        return {};
    }

    // Initialize the count array
    std::vector<int> count(max_val - min_val + 1, 0);

    // Count the occurrences of each value in the input
    for (auto val : input) {
        count[val - min_val]++;
    }

    // Compute the cumulative counts
    for (int I = 1; I < count.size(); i++) {
        count[i] += count[i - 1];
    }

    // Construct the sorted output
    std::vector<int> output(input.size());
    for (auto val : input) {
        output[count[val - min_val] - 1] = val;
        count[val - min_val]--;
    }

    return output;
}

// Main function for testing
int main()
{
    std::vector<int> input = { 3, 5, 2, 8, 7, 5, 3, 1, 3 };
    std::vector<int> output = counting_sort(input);
    for (auto val : output) {
        std::cout << val << " ";
    }
    std::cout << std::endl;
    return 0;
}

In this implementation, the counting_sort() function takes a constant reference to the input list, and returns a sorted list using the counting sort algorithm. Inside the function, we first handle the case of empty input or non-integer values, and then find the minimum and maximum values in the input to determine the range of values. We initialize a count array of the size of the range, and count the occurrences of each value in the input. We then compute the cumulative count to get the position of each value in the sorted output. Finally, we iterate over the input and place each value in the correct position in the output using the count array.

