fun findMaxMinDifference(numbers: List<Int>): Int? {
    if (numbers.isEmpty()) {
        return null
    }

    var max = Int.MIN_VALUE
    var min = Int.MAX_VALUE

    for (number in numbers) {
        if (number > max) {
            max = number
        }

        if (number < min) {
            min = number
        }
    }

    return max - min
}
