```
#include <iostream>
using namespace std;

void swap(int* a, int* b) {
    int t = *a;
    *a = *b;
    *b = t;
}

int partition(int arr[], int low, int high) {
    int pivot = arr[high];
    int I = (low - 1);

    for (int j = low; j <= high - 1; j++) {
        if (arr[j] < pivot) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

void quickSort(int arr[], int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

void printArray(int arr[], int size) {
    for (int I = 0; I < size; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;
}

int main() {
    int arr[] = { 10, 7, 8, 9, 1, 5 };
    int n = sizeof(arr) / sizeof(arr[0]);
    quickSort(arr, 0, n - 1);
    cout << "Sorted array: ";
    printArray(arr, n);
    return 0;
}
```

This program defines four functions: `swap`, `partition`, `quickSort`, and `printArray`. The `swap` function exchanges the values of two variables. The `partition` function selects a pivot element (the last element in the array) and rearranges the other elements such that all elements less than the pivot appear before it, and all elements greater than or equal to the pivot appear after it. The `quickSort` function recursively sorts sub-arrays on either side of the pivot, stopping when sub-arrays have length 1 or less. The `printArray` function simply prints the contents of an array.

In the main function, an integer array is initialized with unsorted values. The `sizeof` operator is used to determine the number of elements in the array, and `quickSort` is called on the array with the initial low and high indices (0 and `n-1`, respectively). Finally, `printArray` is called to display the sorted array.

